using MediatR; using InventorySystem.Application.Features.Products.Commands; using InventorySystem.Application.Features.Products.Queries; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc;
namespace InventorySystem.API.Controllers;
[ApiController][Route("api/products")] public class ProductsController(IMediator mediator):ControllerBase { [HttpPost][Authorize(Roles="Admin,Manager")] public async Task<IActionResult> Create(CreateProductCommand c)=>Ok(new{id=await mediator.Send(c)}); [HttpGet] public async Task<IActionResult> Get([FromQuery]GetProductsQuery q)=>Ok(await mediator.Send(q)); [HttpGet("{id:int}")] public async Task<IActionResult> GetById(int id)=>Ok(await mediator.Send(new GetProductByIdQuery(id))); [HttpPut("{id:int}")][Authorize(Roles="Admin,Manager")] public async Task<IActionResult> Update(int id,UpdateProductCommand c){ if(id!=c.Id) return BadRequest(new{error="Id mismatch."}); await mediator.Send(c); return NoContent(); } [HttpDelete("{id:int}")][Authorize(Roles="Admin,Manager")] public async Task<IActionResult> Delete(int id){ await mediator.Send(new DeleteProductCommand(id)); return NoContent(); } }
